// Auto-generated full HTML sections from Docs/05_browser_extension.html
export const EXTENSION_HTML = {
  "s1": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F310;</div>\n      <h2 class=\"section-title\">Why a Chrome Extension &mdash; Strategic Rationale</h2>\n    </div>\n    <p class=\"section-lead\">The Problem Statement explicitly requires that sensitive data must NOT be shared with cloud providers. A browser extension is the <em>only</em> technology that satisfies all five PS constraints simultaneously.</p>\n    <div class=\"highlight-row\">\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F512;</span><div class=\"hl-title\">Privacy Enforcement Point</div><div class=\"hl-body\">Extensions run in the same process as the browser page but in an isolated world. They can intercept, analyze, and redact data before it ever reaches the network.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F9E0;</span><div class=\"hl-title\">On-Device Intelligence</div><div class=\"hl-body\">Extensions can host ML models (via WebGPU), run inference locally, and access the GPU without requiring native app installation &mdash; zero friction for the user.</div></div>\n      <div class=\"hl-card\"><span class=\"hl-icon\">&#x1F916;</span><div class=\"hl-title\">DOM + Pixel Access</div><div class=\"hl-body\">Extensions uniquely have access to both the page DOM (via content scripts) AND the visual pixel buffer (via captureVisibleTab) &mdash; enabling the dual-channel perception pipeline.</div></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F4CA; Competitive Analysis: Extension vs Alternatives</div>\n      <div class=\"card-body\">\n        <table class=\"perm-table\">\n          <thead><tr><th>Approach</th><th>DOM Access</th><th>Pixel Capture</th><th>Local ML</th><th>No Data Leak</th><th>User Friction</th></tr></thead>\n          <tbody>\n            <tr><td><strong>Chrome Extension</strong> &#x2705;</td><td>&#x2705; Full</td><td>&#x2705; captureVisibleTab</td><td>&#x2705; WebGPU/WASM</td><td>&#x2705; Guaranteed</td><td>&#x2705; One-click install</td></tr>\n            <tr><td>Web App (cloud-hosted)</td><td>&#x274C; None</td><td>&#x274C; None</td><td>&#x26A0; Possible but slow</td><td>&#x274C; Cloud sees all</td><td>&#x2705; Low</td></tr>\n            <tr><td>Native Desktop App</td><td>&#x26A0; OS-level only</td><td>&#x26A0; Screen share</td><td>&#x2705; Full GPU</td><td>&#x2705; Yes</td><td>&#x274C; High (install)</td></tr>\n            <tr><td>Browser WebApp + WebRTC</td><td>&#x274C; None</td><td>&#x26A0; getDisplayMedia (needs consent per session)</td><td>&#x26A0; Limited</td><td>&#x274C; Stream goes to server</td><td>&#x274C; High friction</td></tr>\n            <tr><td>Puppeteer / Playwright Bot</td><td>&#x2705; Full</td><td>&#x2705; Screenshots</td><td>&#x274C; External process</td><td>&#x274C; Server-side</td><td>&#x274C; No user context</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>",
  "s2": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4C4;</div>\n      <h2 class=\"section-title\">Manifest V3 Architecture &mdash; Key Changes</h2>\n    </div>\n    <p class=\"section-lead\">Manifest V3 (MV3) is the current and future standard for Chrome extensions. It introduces important architectural changes from MV2 that directly impact how PRATYAKSHA must be built. Understanding these constraints is critical for the team.</p>\n    <div class=\"callout red\">\n      <div class=\"callout-icon\">&#x26A0;&#xFE0F;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Critical MV3 Constraint: Service Worker Lifecycle</div>In MV3, background pages are replaced by <strong>Service Workers</strong>. Service workers are <em>ephemeral</em> &mdash; they spin up on demand and can be killed by Chrome after ~30 seconds of inactivity. You CANNOT store state in global variables. All persistent state must go to <span class=\"mono\">chrome.storage</span> or IndexedDB.</div>\n    </div>\n    <div class=\"manifest-grid\">\n      <div class=\"mf-card\"><div class=\"mf-key\">Background Page (MV2) &#x2192; Service Worker (MV3)</div><div class=\"mf-val\">Background scripts now run as ephemeral Service Workers. They wake up on events and sleep when idle. PRATYAKSHA's main orchestration logic lives in the Service Worker and must be designed to be stateless.</div></div>\n      <div class=\"mf-card\"><div class=\"mf-key\">XMLHttpRequest &#x2192; fetch() only</div><div class=\"mf-val\">Service Workers only support the Fetch API. No XMLHttpRequest. All API calls to cloud services must use <span class=\"mono\">fetch()</span>. This is fine &mdash; we use fetch + WebSocket for streaming.</div></div>\n      <div class=\"mf-card\"><div class=\"mf-key\">Background DOM Access &#x2192; Offscreen Documents</div><div class=\"mf-val\">Service Workers have no DOM access and no WebGPU. For GPU-accelerated ONNX inference, we must use a Chrome Offscreen Document &mdash; a hidden HTML page that runs continuously and holds the WebGPU context.</div></div>\n      <div class=\"mf-card\"><div class=\"mf-key\">Remote Code &#x2192; Bundled Code Only</div><div class=\"mf-val\">MV3 prohibits loading and executing remotely-hosted code. All JavaScript, ONNX models, and assets must be bundled within the extension package. Models are fetched from the extension's own CRX bundle or local CacheStorage.</div></div>\n      <div class=\"mf-card\"><div class=\"mf-key\">webRequest (blocking) &#x2192; declarativeNetRequest</div><div class=\"mf-val\">Blocking webRequest API is removed. For URL filtering/blocking, use declarativeNetRequest with static rulesets. PRATYAKSHA doesn't need to block requests, but this matters for understanding the permission model.</div></div>\n      <div class=\"mf-card\"><div class=\"mf-key\">Persistent Side Panel (new MV3 feature)</div><div class=\"mf-val\">Chrome 114+ introduces the Side Panel API &mdash; a persistent UI panel attached to the browser window. PRATYAKSHA's main UI (task input, approval flow, action history) lives here. Accessible via <span class=\"mono\">chrome.sidePanel</span>.</div></div>\n    </div>\n    <div class=\"callout green\">\n      <div class=\"callout-icon\">&#x2705;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">PRATYAKSHA's MV3 Compatibility Strategy</div>Every PRATYAKSHA component has been designed specifically for MV3 constraints: Service Worker for event routing, Offscreen Document for WebGPU, IndexedDB for persistent Vault storage, Side Panel for persistent UI. No MV2 workarounds needed.</div>\n    </div>",
  "s3": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F5C2;&#xFE0F;</div>\n      <h2 class=\"section-title\">Project File Structure</h2>\n    </div>\n    <p class=\"section-lead\">The extension is structured as a pure Vanilla JS project (no framework) with a clear separation between the different execution contexts (Service Worker, Offscreen Document, Content Script, Side Panel). Models and heavy assets are stored in a separate directory and loaded lazily.</p>\n    <div class=\"file-tree\"><code><span class=\"ft-dir\">pratyaksha-extension/</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-manifest\">manifest.json</span>              <span class=\"ft-comment\"># Extension manifest (MV3)</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">background/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">service-worker.js</span>        <span class=\"ft-comment\"># Main SW: event routing, API calls, state mgmt</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">offscreen.html</span>           <span class=\"ft-comment\"># Offscreen document host for WebGPU context</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">content/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">content-main.js</span>          <span class=\"ft-comment\"># Injected into every tab: DOM extraction + event dispatch</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">dom-extractor.js</span>         <span class=\"ft-comment\"># Extracts semantic node tree from active page DOM</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">vision/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">vision-worker.js</span>         <span class=\"ft-comment\"># Loaded in Offscreen Doc: orchestrates ONNX pipeline</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">face-detector.js</span>         <span class=\"ft-comment\"># YOLOv8-nano wrapper</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">text-detector.js</span>         <span class=\"ft-comment\"># DBNet-small wrapper</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">ocr-engine.js</span>            <span class=\"ft-comment\"># Indic CRNN OCR wrapper</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">content-classifier.js</span>    <span class=\"ft-comment\"># MobileNetV4-tiny wrapper</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">vault/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">vault-service.js</span>         <span class=\"ft-comment\"># PII pseudonymisation + IndexedDB + AES-256-GCM</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">pii-detector.js</span>          <span class=\"ft-comment\"># Regex-based PII scanner (Aadhaar, PAN, phone)</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">agent/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">agent-runner.js</span>          <span class=\"ft-comment\"># Executes action plans via DOM events</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">action-executor.js</span>       <span class=\"ft-comment\"># CLICK, TYPE, SCROLL, WAIT, ASSERT implementations</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">rollback-stack.js</span>        <span class=\"ft-comment\"># Undo/rollback for executed action sequences</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">sidepanel/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-html\">panel.html</span>               <span class=\"ft-comment\"># Side Panel HTML shell</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">panel.js</span>                 <span class=\"ft-comment\"># Panel UI logic: task input, approval flow, history</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-css\">panel.css</span>                <span class=\"ft-comment\"># Panel styling (warm cream + espresso theme)</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">popup/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-html\">popup.html</span>               <span class=\"ft-comment\"># Extension toolbar popup</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">popup.js</span>                 <span class=\"ft-comment\"># Quick controls: enable/disable, vault status</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">models/</span>                      <span class=\"ft-comment\"># ONNX model weights (INT8 quantized)</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-onnx\">yolov8n-face-int8.onnx</span>   <span class=\"ft-comment\"># Face detector (~6 MB)</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-onnx\">dbnet-small-int8.onnx</span>    <span class=\"ft-comment\"># Text region detector (~8 MB)</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-onnx\">indic-crnn-int8.onnx</span>     <span class=\"ft-comment\"># Indic OCR (~25 MB)</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-onnx\">mobilenetv4-tiny-int8.onnx</span> <span class=\"ft-comment\"># Content classifier (~6 MB)</span>\n<span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> <span class=\"ft-dir\">api/</span>\n<span class=\"ft-comment\">&#x2502;   &#x251C;&#x2500;&#x2500;</span> <span class=\"ft-js\">cloud-client.js</span>          <span class=\"ft-comment\"># HTTPS + WebSocket client for cloud services</span>\n<span class=\"ft-comment\">&#x2502;   &#x2514;&#x2500;&#x2500;</span> <span class=\"ft-js\">auth-manager.js</span>          <span class=\"ft-comment\"># JWT storage (chrome.storage.session) + refresh</span>\n<span class=\"ft-comment\">&#x2514;&#x2500;&#x2500;</span> <span class=\"ft-dir\">assets/</span>\n    <span class=\"ft-comment\">&#x251C;&#x2500;&#x2500;</span> icons/, fonts/             <span class=\"ft-comment\"># Extension icons and bundled fonts</span></code></div>",
  "s4": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F9E9;</div>\n      <h2 class=\"section-title\">Extension Components &mdash; Deep Dive</h2>\n    </div>\n    <p class=\"section-lead\">Each extension component runs in a different execution context with different APIs, permissions, and lifecycle characteristics. Understanding these contexts is critical for correct implementation.</p>\n    <div class=\"comp-grid\">\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-orange\">&#x2699;&#xFE0F;</div><div><div class=\"comp-name\">Service Worker</div><div class=\"comp-file\">background/service-worker.js</div></div></div>\n        <p class=\"comp-desc\">The main orchestrator. Runs ephemerally &mdash; wakes on events, sleeps when idle. Routes messages between all other contexts. Manages the cloud API session (JWT, WebSocket). Handles all <span class=\"mono\">chrome.*</span> API calls that require extension permissions (tabs, storage, scripting). <strong>Must be stateless</strong> &mdash; all state persisted to <span class=\"mono\">chrome.storage.session</span>.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">chrome.runtime</span><span class=\"api-tag\">chrome.tabs</span><span class=\"api-tag\">chrome.scripting</span><span class=\"api-tag\">chrome.storage.session</span><span class=\"api-tag\">fetch()</span></div>\n      </div>\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-blue\">&#x1F5A5;&#xFE0F;</div><div><div class=\"comp-name\">Offscreen Document</div><div class=\"comp-file\">background/offscreen.html</div></div></div>\n        <p class=\"comp-desc\">A hidden HTML page created and managed by the Service Worker via <span class=\"mono\">chrome.offscreen.createDocument()</span>. This is the <strong>only</strong> context in MV3 that has both a DOM and GPU access. Hosts all 4 ONNX models and the WebGPU inference session. Communicates via <span class=\"mono\">chrome.runtime.sendMessage()</span>. Created once and kept alive for the session.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">WebGPU API</span><span class=\"api-tag\">ONNX Runtime Web</span><span class=\"api-tag\">Canvas API</span><span class=\"api-tag\">chrome.runtime.onMessage</span></div>\n      </div>\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-green\">&#x1F4C3;</div><div><div class=\"comp-name\">Content Script</div><div class=\"comp-file\">content/content-main.js</div></div></div>\n        <p class=\"comp-desc\">Injected into every tab page (or specific URL patterns). Runs in an <strong>isolated world</strong> &mdash; has access to the page DOM but not page JS variables. Responsible for: DOM extraction (building the semantic node tree), executing DOM events on behalf of the Agent Runner, and observing DOM mutations for change detection.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">document DOM</span><span class=\"api-tag\">MutationObserver</span><span class=\"api-tag\">dispatchEvent()</span><span class=\"api-tag\">chrome.runtime.sendMessage</span></div>\n      </div>\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-amber\">&#x1F4BB;</div><div><div class=\"comp-name\">Side Panel</div><div class=\"comp-file\">sidepanel/panel.html</div></div></div>\n        <p class=\"comp-desc\">The primary user interface. A persistent panel attached to the browser window (Chrome 114+). Contains: task input textarea, real-time action preview stream, step-by-step approval buttons, vault status indicator, and action history log. Communicates with the Service Worker via <span class=\"mono\">chrome.runtime.sendMessage()</span>.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">chrome.sidePanel</span><span class=\"api-tag\">chrome.runtime</span><span class=\"api-tag\">Vanilla JS DOM</span></div>\n      </div>\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-purple\">&#x1F512;</div><div><div class=\"comp-name\">Vault Service</div><div class=\"comp-file\">vault/vault-service.js</div></div></div>\n        <p class=\"comp-desc\">A pure-JS class shared across contexts (loaded in Service Worker and Offscreen Document). Manages the IndexedDB <span class=\"mono\">pratyaksha_vault</span> database. Exposes three core methods: <span class=\"mono\">tokenize(piiValue, type)</span> \u2192 token, <span class=\"mono\">rehydrate(token)</span> \u2192 piiValue, <span class=\"mono\">purgeSession()</span>. All data encrypted with AES-256-GCM before write.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">IndexedDB</span><span class=\"api-tag\">Web Crypto API</span><span class=\"api-tag\">AES-256-GCM</span><span class=\"api-tag\">PBKDF2</span></div>\n      </div>\n      <div class=\"comp-card\">\n        <div class=\"comp-header\"><div class=\"comp-icon ci-teal\">&#x1F916;</div><div><div class=\"comp-name\">Agent Runner</div><div class=\"comp-file\">agent/agent-runner.js</div></div></div>\n        <p class=\"comp-desc\">Loaded via <span class=\"mono\">chrome.scripting.executeScript()</span> into the target tab. Receives rehydrated action plans and executes them step-by-step: clicking elements, typing text, scrolling, waiting for assertions. Maintains a rollback stack. Dispatches <span class=\"mono\">CustomEvent('pratyaksha:step-done')</span> after each step for the UI to consume.</p>\n        <div class=\"comp-apis\"><span class=\"api-tag\">dispatchEvent</span><span class=\"api-tag\">InputEvent</span><span class=\"api-tag\">MouseEvent</span><span class=\"api-tag\">KeyboardEvent</span><span class=\"api-tag\">MutationObserver</span></div>\n      </div>\n    </div>",
  "s5": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4AC;</div>\n      <h2 class=\"section-title\">Message Passing Protocol</h2>\n    </div>\n    <p class=\"section-lead\">Chrome extensions use a strict message passing model between contexts. All inter-context communication goes through <span class=\"mono\">chrome.runtime.sendMessage()</span> (one-shot) or <span class=\"mono\">chrome.runtime.connect()</span> (persistent port). PRATYAKSHA uses a typed message protocol to keep all communication clear and auditable.</p>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// Typed Message Protocol \u2014 all messages follow this schema</span>\n<span class=\"code-key\">const</span> MessageTypes = {\n  <span class=\"code-comment\">// Side Panel \u2192 Service Worker</span>\n  START_TASK:          <span class=\"code-str\">'START_TASK'</span>,         <span class=\"code-comment\">// { task: string }</span>\n  CANCEL_TASK:         <span class=\"code-str\">'CANCEL_TASK'</span>,        <span class=\"code-comment\">// { task_id: string }</span>\n  APPROVE_STEP:        <span class=\"code-str\">'APPROVE_STEP'</span>,       <span class=\"code-comment\">// { step_index: number }</span>\n  REJECT_STEP:         <span class=\"code-str\">'REJECT_STEP'</span>,        <span class=\"code-comment\">// { step_index: number, reason: string }</span>\n  GET_VAULT_STATUS:    <span class=\"code-str\">'GET_VAULT_STATUS'</span>,   <span class=\"code-comment\">// {} \u2014 returns token count, size</span>\n  \n  <span class=\"code-comment\">// Service Worker \u2192 Side Panel (via port)</span>\n  TASK_STARTED:        <span class=\"code-str\">'TASK_STARTED'</span>,       <span class=\"code-comment\">// { task_id: string }</span>\n  STEP_PENDING:        <span class=\"code-str\">'STEP_PENDING'</span>,       <span class=\"code-comment\">// { step: ActionStep, reasoning: string }</span>\n  STEP_DONE:           <span class=\"code-str\">'STEP_DONE'</span>,          <span class=\"code-comment\">// { step_index, success, latency_ms }</span>\n  TASK_COMPLETE:       <span class=\"code-str\">'TASK_COMPLETE'</span>,      <span class=\"code-comment\">// { task_id, total_steps, duration_ms }</span>\n  ERROR:               <span class=\"code-str\">'ERROR'</span>,              <span class=\"code-comment\">// { code, message, step_index? }</span>\n\n  <span class=\"code-comment\">// Service Worker \u2192 Offscreen Document</span>\n  RUN_VISION:          <span class=\"code-str\">'RUN_VISION'</span>,         <span class=\"code-comment\">// { imageDataUrl: string }</span>\n  VISION_RESULT:       <span class=\"code-str\">'VISION_RESULT'</span>,      <span class=\"code-comment\">// { sceneGraph: SceneGraph, sanitizedDataUrl: string }</span>\n\n  <span class=\"code-comment\">// Service Worker \u2192 Content Script</span>\n  EXTRACT_DOM:         <span class=\"code-str\">'EXTRACT_DOM'</span>,        <span class=\"code-comment\">// {} \u2014 triggers DOM extraction</span>\n  EXECUTE_ACTION:      <span class=\"code-str\">'EXECUTE_ACTION'</span>,     <span class=\"code-comment\">// { action: RehydratedAction }</span>\n};</code></div>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F504; Typical Task Execution Message Flow</div>\n      <div class=\"card-body\">\n        <ol style=\"font-size:14px;line-height:2;padding-left:20px;color:var(--text-body)\">\n          <li>User types task in Side Panel &#x2192; sends <span class=\"mono\">START_TASK</span> to Service Worker</li>\n          <li>Service Worker calls <span class=\"mono\">chrome.tabs.captureVisibleTab()</span> &#x2192; gets screenshot DataURL</li>\n          <li>Service Worker sends <span class=\"mono\">RUN_VISION</span> to Offscreen Document with screenshot</li>\n          <li>Offscreen Document runs 4 ONNX models &#x2192; returns <span class=\"mono\">VISION_RESULT</span> with scene graph</li>\n          <li>Service Worker sends <span class=\"mono\">EXTRACT_DOM</span> to Content Script &#x2192; gets DOM node tree</li>\n          <li>Service Worker calls Vault Service: tokenize all PII in scene graph + DOM</li>\n          <li>Service Worker sends sanitized canvas + tokenized scene graph to Cloud Orchestrator</li>\n          <li>Cloud Orchestrator streams action plan via WebSocket &#x2192; Service Worker receives steps</li>\n          <li>For each step, Service Worker sends <span class=\"mono\">STEP_PENDING</span> to Side Panel for user approval</li>\n          <li>User approves &#x2192; Service Worker calls Vault Service to rehydrate tokens &#x2192; sends <span class=\"mono\">EXECUTE_ACTION</span> to Content Script</li>\n          <li>Content Script dispatches real DOM events &#x2192; returns success/failure</li>\n          <li>Service Worker sends <span class=\"mono\">STEP_DONE</span> to Side Panel &#x2192; loop continues</li>\n        </ol>\n      </div>\n    </div>",
  "s6": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4F8;</div>\n      <h2 class=\"section-title\">Screen Capture Pipeline</h2>\n    </div>\n    <p class=\"section-lead\">Screen capture is the first step of the perception pipeline. PRATYAKSHA uses <span class=\"mono\">chrome.tabs.captureVisibleTab()</span> &mdash; the only Chrome API that captures a high-fidelity screenshot of the current tab without requiring screen sharing permission from the user.</p>\n    <div class=\"callout green\">\n      <div class=\"callout-icon\">&#x2705;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Privacy Advantage</div><span class=\"mono\">chrome.tabs.captureVisibleTab()</span> does NOT trigger the browser's screen sharing permission dialog. It is a silent, extension-internal API that captures only the active tab, not the entire screen or other apps. This is crucial for a low-friction privacy-preserving workflow.</div>\n    </div>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// service-worker.js \u2014 Screen capture pipeline</span>\n<span class=\"code-key\">async function</span> <span class=\"code-fn\">captureAndProcess</span>(tabId) {\n  <span class=\"code-comment\">// Step 1: Capture the visible tab as JPEG (quality 90 = good quality, smaller size)</span>\n  <span class=\"code-key\">const</span> imageDataUrl = <span class=\"code-key\">await</span> chrome.tabs.captureVisibleTab(<span class=\"code-key\">null</span>, {\n    format: <span class=\"code-str\">'jpeg'</span>,\n    quality: <span class=\"code-val\">90</span>\n  });\n  \n  <span class=\"code-comment\">// Step 2: Send to Offscreen Document for ONNX inference (never sent to network)</span>\n  <span class=\"code-key\">const</span> visionResult = <span class=\"code-key\">await</span> <span class=\"code-fn\">sendToOffscreen</span>({\n    type: <span class=\"code-str\">'RUN_VISION'</span>,\n    payload: { imageDataUrl }     <span class=\"code-comment\">// stays inside extension process</span>\n  });\n  \n  <span class=\"code-comment\">// Step 3: Vault tokenizes PII, returns sanitizedDataUrl (PII blacked out)</span>\n  <span class=\"code-key\">const</span> { sanitizedDataUrl, tokenizedSceneGraph } = <span class=\"code-key\">await</span> vaultService.<span class=\"code-fn\">sanitize</span>(\n    visionResult.sceneGraph,\n    visionResult.rawCanvas      <span class=\"code-comment\">// raw canvas only exists inside extension</span>\n  );\n  \n  <span class=\"code-comment\">// ONLY sanitizedDataUrl and tokenizedSceneGraph leave the extension</span>\n  <span class=\"code-key\">return</span> { sanitizedDataUrl, tokenizedSceneGraph };\n}</code></div>\n    <div class=\"callout warn\">\n      <div class=\"callout-icon\">&#x26A0;&#xFE0F;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Handling Non-DOM Content (The Core PS Problem)</div>PDFs rendered via Chrome PDF Viewer, embedded images in forms, canvas-rendered content (DigiLocker documents), and SVG infographics are <strong>invisible to DOM extraction</strong>. The pixel capture + ONNX pipeline is the <em>only</em> way to read these. This is why the Vision Worker is non-optional, not a nice-to-have.</div>\n    </div>",
  "s7": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F5FA;&#xFE0F;</div>\n      <h2 class=\"section-title\">DOM Extraction Strategy</h2>\n    </div>\n    <p class=\"section-lead\">The DOM extractor builds a compact, structured representation of the page that the cloud Orchestrator can reason about to identify actionable elements (buttons, inputs, links) without access to the full page HTML (which might contain PII in text).</p>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// content/dom-extractor.js \u2014 Builds a clean, safe semantic node tree</span>\n<span class=\"code-key\">function</span> <span class=\"code-fn\">extractSemanticTree</span>() {\n  <span class=\"code-key\">const</span> INTERACTIVE = [<span class=\"code-str\">'a'</span>, <span class=\"code-str\">'button'</span>, <span class=\"code-str\">'input'</span>, <span class=\"code-str\">'select'</span>, <span class=\"code-str\">'textarea'</span>];\n  <span class=\"code-key\">const</span> SEMANTIC   = [<span class=\"code-str\">'h1'</span>,<span class=\"code-str\">'h2'</span>,<span class=\"code-str\">'h3'</span>,<span class=\"code-str\">'label'</span>,<span class=\"code-str\">'p'</span>,<span class=\"code-str\">'span'</span>,<span class=\"code-str\">'td'</span>,<span class=\"code-str\">'li'</span>];\n\n  <span class=\"code-key\">return</span> [...document.<span class=\"code-fn\">querySelectorAll</span>([...INTERACTIVE, ...SEMANTIC].<span class=\"code-fn\">join</span>(<span class=\"code-str\">','</span>))]\n    .<span class=\"code-fn\">filter</span>(el => el.<span class=\"code-fn\">getBoundingClientRect</span>().width > <span class=\"code-val\">0</span>)  <span class=\"code-comment\">// visible only</span>\n    .<span class=\"code-fn\">map</span>(el => {\n      <span class=\"code-key\">const</span> rect = el.<span class=\"code-fn\">getBoundingClientRect</span>();\n      <span class=\"code-key\">return</span> {\n        tag:      el.tagName.<span class=\"code-fn\">toLowerCase</span>(),\n        role:     el.<span class=\"code-fn\">getAttribute</span>(<span class=\"code-str\">'role'</span>) || <span class=\"code-key\">null</span>,\n        aria:     el.<span class=\"code-fn\">getAttribute</span>(<span class=\"code-str\">'aria-label'</span>) || <span class=\"code-key\">null</span>,\n        text:     el.innerText?.<span class=\"code-fn\">slice</span>(<span class=\"code-val\">0</span>, <span class=\"code-val\">120</span>),  <span class=\"code-comment\">// NOTE: PII scanner runs on this text</span>\n        type:     el.type || <span class=\"code-key\">null</span>,            <span class=\"code-comment\">// for input elements</span>\n        name:     el.name || <span class=\"code-key\">null</span>,\n        selector: <span class=\"code-fn\">buildUniqueSelector</span>(el),     <span class=\"code-comment\">// CSS selector for Agent Runner</span>\n        bbox:     { x: rect.x, y: rect.y, w: rect.width, h: rect.height },\n        visible:  <span class=\"code-key\">true</span>\n      };\n    });\n}</code></div>\n    <div class=\"callout blue\">\n      <div class=\"callout-icon\">&#x1F4A1;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">PII Scanner on DOM Text</div>All <span class=\"mono\">text</span> fields in the extracted node tree are passed through the PII scanner before being included in the tokenized scene graph. Any Aadhaar/PAN numbers or phone numbers found in DOM text are replaced with tokens in the JSON sent to the cloud, even if the Vision Worker didn't detect them visually.</div>\n    </div>",
  "s8": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x26A1;</div>\n      <h2 class=\"section-title\">WebGPU in Chrome Extension &mdash; Implementation</h2>\n    </div>\n    <p class=\"section-lead\">WebGPU gives PRATYAKSHA direct access to the GPU for inference without any native drivers or plugins. It is the key technical enabler for sub-200ms on-device vision inference inside the browser.</p>\n    <div class=\"callout orange\">\n      <div class=\"callout-icon\">&#x26A0;&#xFE0F;</div>\n      <div class=\"callout-body\"><div class=\"callout-title\">Service Worker Cannot Use WebGPU</div>The MV3 Service Worker runs in a Web Worker context without a DOM or GPU context. <strong>All WebGPU calls must happen inside the Offscreen Document</strong>, which is a full HTML page with a rendering context. The Service Worker creates the Offscreen Document once on startup and uses message passing to send work to it.</div>\n    </div>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// vision/vision-worker.js \u2014 Runs inside offscreen.html</span>\n\n<span class=\"code-key\">let</span> ort, sessions = {};\n\n<span class=\"code-key\">async function</span> <span class=\"code-fn\">initModels</span>() {\n  <span class=\"code-comment\">// Import ONNX Runtime Web (bundled in extension package)</span>\n  ort = <span class=\"code-key\">await</span> <span class=\"code-fn\">import</span>(<span class=\"code-str\">'../lib/ort.webgpu.min.js'</span>);\n\n  <span class=\"code-comment\">// Prefer WebGPU, fall back to WASM if unavailable (e.g., low-end devices)</span>\n  ort.<span class=\"code-type\">env</span>.wasm.numThreads = <span class=\"code-val\">4</span>;\n  \n  <span class=\"code-key\">const</span> options = {\n    executionProviders: [<span class=\"code-str\">'webgpu'</span>, <span class=\"code-str\">'wasm'</span>],  <span class=\"code-comment\">// webgpu first, wasm fallback</span>\n    graphOptimizationLevel: <span class=\"code-str\">'all'</span>,\n    enableCpuMemArena: <span class=\"code-key\">false</span>,\n  };\n\n  <span class=\"code-comment\">// Load model weights from extension bundle (no network request)</span>\n  sessions.face       = <span class=\"code-key\">await</span> ort.InferenceSession.<span class=\"code-fn\">create</span>(<span class=\"code-str\">'./models/yolov8n-face-int8.onnx'</span>, options);\n  sessions.textDetect = <span class=\"code-key\">await</span> ort.InferenceSession.<span class=\"code-fn\">create</span>(<span class=\"code-str\">'./models/dbnet-small-int8.onnx'</span>, options);\n  sessions.ocr        = <span class=\"code-key\">await</span> ort.InferenceSession.<span class=\"code-fn\">create</span>(<span class=\"code-str\">'./models/indic-crnn-int8.onnx'</span>, options);\n  sessions.classify   = <span class=\"code-key\">await</span> ort.InferenceSession.<span class=\"code-fn\">create</span>(<span class=\"code-str\">'./models/mobilenetv4-tiny-int8.onnx'</span>, options);\n\n  <span class=\"code-fn\">postMessage</span>({ type: <span class=\"code-str\">'MODELS_READY'</span> });\n}\n\n<span class=\"code-comment\">// Handle vision request from Service Worker</span>\n<span class=\"code-fn\">chrome.runtime.onMessage.addListener</span>(<span class=\"code-key\">async</span> (msg) => {\n  <span class=\"code-key\">if</span> (msg.type === <span class=\"code-str\">'RUN_VISION'</span>) {\n    <span class=\"code-key\">const</span> { imageDataUrl } = msg.payload;\n    <span class=\"code-key\">const</span> imageBitmap = <span class=\"code-key\">await</span> <span class=\"code-fn\">decodeImage</span>(imageDataUrl);\n    \n    <span class=\"code-key\">const</span> [faces, textRegions, classification] = <span class=\"code-key\">await</span> Promise.<span class=\"code-fn\">all</span>([\n      <span class=\"code-fn\">runFaceDetection</span>(sessions.face, imageBitmap),\n      <span class=\"code-fn\">runTextDetection</span>(sessions.textDetect, imageBitmap),\n      <span class=\"code-fn\">runClassification</span>(sessions.classify, imageBitmap),\n    ]);\n    \n    <span class=\"code-comment\">// OCR runs on detected text regions only (not whole image)</span>\n    <span class=\"code-key\">const</span> ocrResults = <span class=\"code-key\">await</span> <span class=\"code-fn\">runOCR</span>(sessions.ocr, imageBitmap, textRegions);\n    \n    <span class=\"code-key\">return</span> { sceneGraph: <span class=\"code-fn\">buildSceneGraph</span>(faces, textRegions, ocrResults, classification) };\n  }\n});</code></div>",
  "s9": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F512;</div>\n      <h2 class=\"section-title\">Vault &amp; Privacy Layer</h2>\n    </div>\n    <p class=\"section-lead\">The Vault Service is the privacy enforcement centrepiece of PRATYAKSHA. It is responsible for converting raw PII into opaque tokens before data leaves the local context, and converting tokens back to real values for action execution.</p>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// vault/vault-service.js \u2014 Core Vault implementation</span>\n\n<span class=\"code-key\">class</span> <span class=\"code-type\">VaultService</span> {\n  <span class=\"code-key\">constructor</span>() {\n    <span class=\"code-key\">this</span>.db = <span class=\"code-key\">null</span>;\n    <span class=\"code-key\">this</span>.encKey = <span class=\"code-key\">null</span>;\n    <span class=\"code-key\">this</span>.sessionId = crypto.<span class=\"code-fn\">randomUUID</span>();\n  }\n\n  <span class=\"code-key\">async</span> <span class=\"code-fn\">init</span>(userPin) {\n    <span class=\"code-comment\">// Derive AES-256-GCM key from user PIN + device fingerprint</span>\n    <span class=\"code-key\">const</span> salt = <span class=\"code-key\">await</span> <span class=\"code-fn\">getDeviceFingerprint</span>();\n    <span class=\"code-key\">const</span> keyMaterial = <span class=\"code-key\">await</span> crypto.subtle.<span class=\"code-fn\">importKey</span>(<span class=\"code-str\">'raw'</span>,\n      <span class=\"code-key\">new</span> TextEncoder().<span class=\"code-fn\">encode</span>(userPin), <span class=\"code-str\">'PBKDF2'</span>, <span class=\"code-key\">false</span>, [<span class=\"code-str\">'deriveKey'</span>]);\n    \n    <span class=\"code-key\">this</span>.encKey = <span class=\"code-key\">await</span> crypto.subtle.<span class=\"code-fn\">deriveKey</span>({\n      name: <span class=\"code-str\">'PBKDF2'</span>, salt, iterations: <span class=\"code-val\">300000</span>, hash: <span class=\"code-str\">'SHA-256'</span>\n    }, keyMaterial, { name: <span class=\"code-str\">'AES-GCM'</span>, length: <span class=\"code-val\">256</span> }, <span class=\"code-key\">false</span>, [<span class=\"code-str\">'encrypt'</span>, <span class=\"code-str\">'decrypt'</span>]);\n    \n    <span class=\"code-key\">this</span>.db = <span class=\"code-key\">await</span> <span class=\"code-fn\">openIndexedDB</span>(<span class=\"code-str\">'pratyaksha_vault'</span>, <span class=\"code-val\">1</span>);\n  }\n\n  <span class=\"code-key\">async</span> <span class=\"code-fn\">tokenize</span>(piiValue, type) {\n    <span class=\"code-comment\">// Generate unique session-scoped token</span>\n    <span class=\"code-key\">const</span> count = <span class=\"code-key\">await</span> <span class=\"code-key\">this</span>.<span class=\"code-fn\">countByType</span>(type);\n    <span class=\"code-key\">const</span> token = <span class=\"code-str\">`\u27e8${type}_${String(count + 1).padStart(2,'0')}\u27e9`</span>;\n    \n    <span class=\"code-comment\">// Encrypt PII value before storing</span>\n    <span class=\"code-key\">const</span> iv = crypto.<span class=\"code-fn\">getRandomValues</span>(<span class=\"code-key\">new</span> Uint8Array(<span class=\"code-val\">12</span>));\n    <span class=\"code-key\">const</span> encrypted = <span class=\"code-key\">await</span> crypto.subtle.<span class=\"code-fn\">encrypt</span>(\n      { name: <span class=\"code-str\">'AES-GCM'</span>, iv }, <span class=\"code-key\">this</span>.encKey,\n      <span class=\"code-key\">new</span> TextEncoder().<span class=\"code-fn\">encode</span>(JSON.<span class=\"code-fn\">stringify</span>({ piiValue, type }))\n    );\n    \n    <span class=\"code-key\">await</span> <span class=\"code-key\">this</span>.db.<span class=\"code-fn\">put</span>(<span class=\"code-str\">'tokens'</span>, { token, encrypted, iv, sessionId: <span class=\"code-key\">this</span>.sessionId });\n    <span class=\"code-key\">return</span> token;  <span class=\"code-comment\">// ONLY the token leaves this function</span>\n  }\n\n  <span class=\"code-key\">async</span> <span class=\"code-fn\">rehydrate</span>(token) {\n    <span class=\"code-key\">const</span> record = <span class=\"code-key\">await</span> <span class=\"code-key\">this</span>.db.<span class=\"code-fn\">get</span>(<span class=\"code-str\">'tokens'</span>, token);\n    <span class=\"code-key\">if</span> (!record) <span class=\"code-key\">throw new</span> <span class=\"code-type\">Error</span>(<span class=\"code-str\">`VAULT_ERROR: Unknown token ${token} \u2014 action blocked`</span>);\n    \n    <span class=\"code-key\">const</span> decrypted = <span class=\"code-key\">await</span> crypto.subtle.<span class=\"code-fn\">decrypt</span>(\n      { name: <span class=\"code-str\">'AES-GCM'</span>, iv: record.iv }, <span class=\"code-key\">this</span>.encKey, record.encrypted\n    );\n    <span class=\"code-key\">return</span> JSON.<span class=\"code-fn\">parse</span>(<span class=\"code-key\">new</span> TextDecoder().<span class=\"code-fn\">decode</span>(decrypted)).piiValue;\n  }\n}</code></div>",
  "s10": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F6E1;&#xFE0F;</div>\n      <h2 class=\"section-title\">Permissions Model &amp; Content Security Policy</h2>\n    </div>\n    <p class=\"section-lead\">The Chrome Web Store review process scrutinises every permission. PRATYAKSHA uses the <strong>minimum necessary permissions</strong> principle. Every permission must be justified with a specific feature, and will be documented in the Web Store submission.</p>\n    <div class=\"card\">\n      <div class=\"card-title\">&#x1F4CB; Manifest Permissions Justification</div>\n      <div class=\"card-body\">\n        <table class=\"perm-table\">\n          <thead><tr><th>Permission</th><th>Justification</th><th>Risk Level</th></tr></thead>\n          <tbody>\n            <tr><td><span class=\"mono\">activeTab</span></td><td>Required to capture the visible tab screenshot via captureVisibleTab()</td><td><span class=\"risk low\">Low</span></td></tr>\n            <tr><td><span class=\"mono\">tabs</span></td><td>Required to call chrome.tabs.captureVisibleTab() &mdash; restricted to active tab only</td><td><span class=\"risk low\">Low</span></td></tr>\n            <tr><td><span class=\"mono\">scripting</span></td><td>Required to inject content script and agent-runner.js into tab for DOM extraction and event dispatch</td><td><span class=\"risk med\">Medium</span></td></tr>\n            <tr><td><span class=\"mono\">storage</span></td><td>chrome.storage.session for ephemeral task state in Service Worker (NOT vault &mdash; vault uses IndexedDB)</td><td><span class=\"risk low\">Low</span></td></tr>\n            <tr><td><span class=\"mono\">offscreen</span></td><td>Required to create the Offscreen Document for WebGPU ONNX inference context</td><td><span class=\"risk low\">Low</span></td></tr>\n            <tr><td><span class=\"mono\">sidePanel</span></td><td>Required to register and control the Chrome Side Panel UI (main user interface)</td><td><span class=\"risk low\">Low</span></td></tr>\n            <tr><td><span class=\"mono\">host_permissions: https://api.pratyaksha.isro.gov.in/*</span></td><td>Required for HTTPS + WebSocket connection to the cloud Orchestrator. Narrowly scoped to PRATYAKSHA API only &mdash; NOT broad host permission.</td><td><span class=\"risk med\">Medium</span></td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n    <div class=\"code-block\"><code><span class=\"code-comment\">// manifest.json \u2014 Complete PRATYAKSHA Manifest V3</span>\n{\n  <span class=\"code-key\">\"manifest_version\"</span>: <span class=\"code-val\">3</span>,\n  <span class=\"code-key\">\"name\"</span>: <span class=\"code-str\">\"PRATYAKSHA \u2014 Privacy-First Browser Agent\"</span>,\n  <span class=\"code-key\">\"version\"</span>: <span class=\"code-str\">\"1.0.0\"</span>,\n  <span class=\"code-key\">\"description\"</span>: <span class=\"code-str\">\"On-device visual perception for browser automation. All PII stays local.\"</span>,\n  <span class=\"code-key\">\"permissions\"</span>: [<span class=\"code-str\">\"activeTab\"</span>, <span class=\"code-str\">\"tabs\"</span>, <span class=\"code-str\">\"scripting\"</span>, <span class=\"code-str\">\"storage\"</span>, <span class=\"code-str\">\"offscreen\"</span>, <span class=\"code-str\">\"sidePanel\"</span>],\n  <span class=\"code-key\">\"host_permissions\"</span>: [<span class=\"code-str\">\"https://api.pratyaksha.isro.gov.in/*\"</span>],\n  <span class=\"code-key\">\"background\"</span>: {\n    <span class=\"code-key\">\"service_worker\"</span>: <span class=\"code-str\">\"background/service-worker.js\"</span>,\n    <span class=\"code-key\">\"type\"</span>: <span class=\"code-str\">\"module\"</span>\n  },\n  <span class=\"code-key\">\"content_scripts\"</span>: [{\n    <span class=\"code-key\">\"matches\"</span>: [<span class=\"code-str\">\"&lt;all_urls&gt;\"</span>],\n    <span class=\"code-key\">\"js\"</span>: [<span class=\"code-str\">\"content/content-main.js\"</span>],\n    <span class=\"code-key\">\"run_at\"</span>: <span class=\"code-str\">\"document_idle\"</span>,\n    <span class=\"code-key\">\"world\"</span>: <span class=\"code-str\">\"ISOLATED\"</span>\n  }],\n  <span class=\"code-key\">\"side_panel\"</span>: { <span class=\"code-key\">\"default_path\"</span>: <span class=\"code-str\">\"sidepanel/panel.html\"</span> },\n  <span class=\"code-key\">\"action\"</span>: { <span class=\"code-key\">\"default_popup\"</span>: <span class=\"code-str\">\"popup/popup.html\"</span> },\n  <span class=\"code-key\">\"content_security_policy\"</span>: {\n    <span class=\"code-key\">\"extension_pages\"</span>: <span class=\"code-str\">\"script-src 'self'; object-src 'none'; connect-src https://api.pratyaksha.isro.gov.in wss://api.pratyaksha.isro.gov.in\"</span>\n  },\n  <span class=\"code-key\">\"web_accessible_resources\"</span>: [{\n    <span class=\"code-key\">\"resources\"</span>: [<span class=\"code-str\">\"models/*.onnx\"</span>, <span class=\"code-str\">\"lib/*.js\"</span>],\n    <span class=\"code-key\">\"matches\"</span>: [<span class=\"code-str\">\"&lt;all_urls&gt;\"</span>]\n  }]\n}</code></div>",
  "s11": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F3A8;</div>\n      <h2 class=\"section-title\">Side Panel UI Design</h2>\n    </div>\n    <p class=\"section-lead\">The Side Panel is the primary user-facing interface. It must be clean, reassuring, and give the user clear visibility and control over everything the AI is doing. The design follows the principle: <strong>\"Show your work, ask before acting.\"</strong></p>\n    <div class=\"comp-grid\">\n      <div class=\"card\">\n        <div class=\"card-title\">&#x1F4DD; Task Input View</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px;color:var(--text-body)\">\n            <li>Large text area for natural language task description</li>\n            <li>Context badge showing current page domain</li>\n            <li>Vault status indicator (green = active, how many tokens stored)</li>\n            <li>Privacy mode toggle (strict / standard)</li>\n            <li>\"Start Agent\" primary CTA button</li>\n            <li>Recent task history (last 5 tasks)</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-title\">&#x23F3; Execution View (Active Task)</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px;color:var(--text-body)\">\n            <li>Real-time AI reasoning trace (collapsible)</li>\n            <li>Current step card: action type + target element + value (tokens shown, never real PII)</li>\n            <li>Large \"Approve &#x2705;\" and \"Skip &#x23ED;\" buttons for each step</li>\n            <li>\"Stop Agent &#x1F6D1;\" emergency button (always visible)</li>\n            <li>Progress bar: steps done / total estimated</li>\n            <li>Live DOM highlight of the element being targeted</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-title\">&#x1F4DC; History &amp; Audit View</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px;color:var(--text-body)\">\n            <li>Chronological log of all past agent actions</li>\n            <li>Each entry: timestamp, domain, action type, success/fail badge</li>\n            <li>Expand each entry to see the full reasoning trace</li>\n            <li>\"Undo Last Task\" button (triggers rollback stack)</li>\n            <li>\"Clear All History\" (calls /ledger/history DELETE)</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-title\">&#x1F512; Vault View</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px;color:var(--text-body)\">\n            <li>Summary: N faces, N Aadhaar numbers, N PAN cards detected this session</li>\n            <li>Token list: shows token names (e.g., &#x27E8;AADHAAR_01&#x27E9;) but never real values</li>\n            <li>\"Lock Vault\" button: encrypts and clears session keys from memory</li>\n            <li>\"Clear Session Vault\" button: purges all IndexedDB records</li>\n            <li>Session duration + total PII items protected this session</li>\n          </ul>\n        </div>\n      </div>\n    </div>",
  "s12": "<div class=\"section-header\">\n      <div class=\"section-icon-badge\">&#x1F4E6;</div>\n      <h2 class=\"section-title\">Build &amp; Distribution</h2>\n    </div>\n    <p class=\"section-lead\">The extension is built using a minimal Vite config (for bundling only &mdash; no framework). The build output is a clean MV3-compliant extension directory that can be loaded unpacked in Chrome or submitted to the Web Store.</p>\n    <div class=\"comp-grid\">\n      <div class=\"card\">\n        <div class=\"card-title\">&#x1F6E0;&#xFE0F; Build Tooling</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px\">\n            <li><strong>Bundler:</strong> Vite + CRXJS plugin (Chrome extension aware bundler)</li>\n            <li><strong>Language:</strong> Vanilla JS (ES2022 modules) &mdash; no TS for now (faster iteration)</li>\n            <li><strong>Model bundling:</strong> ONNX files copied to <span class=\"mono\">dist/models/</span> as-is</li>\n            <li><strong>Hash generation:</strong> SHA-256 hashes of model files auto-generated at build time for integrity check</li>\n            <li><strong>Dev mode:</strong> <span class=\"mono\">vite build --watch</span> + Chrome 'load unpacked' for instant reload</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"card\">\n        <div class=\"card-title\">&#x1F3E6; Chrome Web Store Submission</div>\n        <div class=\"card-body\">\n          <ul style=\"font-size:14px;line-height:2;padding-left:18px\">\n            <li>All permissions justified in the submission form with specific use case per permission</li>\n            <li>Privacy Policy document (in English + Hindi) linked in the store listing</li>\n            <li>Remote code execution: explicitly None (all code bundled)</li>\n            <li>Single purpose statement: \"Privacy-preserving on-device browser automation\"</li>\n            <li>For ISRO internal deployment: enterprise policy-based force-install (no store needed)</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n    <div class=\"security-checklist\">\n      <div class=\"check-group\">\n        <div class=\"check-group-title\">&#x1F527; Pre-Release Security Checklist</div>\n        <div class=\"check-item\">All ONNX model SHA-256 hashes embedded in extension code</div>\n        <div class=\"check-item\">CSP header blocks all inline scripts and external script sources</div>\n        <div class=\"check-item\">IndexedDB Vault encrypted with AES-256-GCM (verified by unit test)</div>\n        <div class=\"check-item\">No PII logged to console.log() in any file (grep-verified at build)</div>\n        <div class=\"check-item\">Rollback stack unit tested with simulated failures</div>\n        <div class=\"check-item\">WebSocket connection uses WSS with cert pinning via Cloudflare</div>\n      </div>\n      <div class=\"check-group\">\n        <div class=\"check-group-title\">&#x1F9EA; Testing Strategy</div>\n        <div class=\"check-item\">Unit tests: Vault Service (tokenize/rehydrate round-trip)</div>\n        <div class=\"check-item\">Unit tests: DOM Extractor on 10 real government portals</div>\n        <div class=\"check-item\">Integration test: Full 7-step pipeline with mock cloud</div>\n        <div class=\"check-item\">Playwright tests: Extension loaded in Chromium, automated task execution</div>\n        <div class=\"check-item\">Manual test: DigiLocker, SBI bank portal, IRCTC booking flow</div>\n        <div class=\"check-item\">Security test: PII leak scanner (verify zero PII in network logs)</div>\n      </div>\n    </div>\n    <div class=\"phase-grid\">\n      <div class=\"phase-card p1\">\n        <div class=\"phase-label\">Week 1&#x2013;2</div>\n        <div class=\"phase-title\">Extension Scaffold</div>\n        <div class=\"phase-item\">Manifest V3 setup + Vite build</div>\n        <div class=\"phase-item\">Service Worker + Offscreen Document boilerplate</div>\n        <div class=\"phase-item\">Side Panel shell UI</div>\n        <div class=\"phase-item\">Message passing protocol implementation</div>\n      </div>\n      <div class=\"phase-card p2\">\n        <div class=\"phase-label\">Week 3&#x2013;5</div>\n        <div class=\"phase-title\">Vision Pipeline</div>\n        <div class=\"phase-item\">ONNX Runtime Web integration + WebGPU</div>\n        <div class=\"phase-item\">All 4 models loaded + tested</div>\n        <div class=\"phase-item\">Vault Service + IndexedDB + AES encryption</div>\n        <div class=\"phase-item\">DOM Extractor + PII Scanner</div>\n      </div>\n      <div class=\"phase-card p3\">\n        <div class=\"phase-label\">Week 6&#x2013;9</div>\n        <div class=\"phase-title\">Agent &amp; Cloud Integration</div>\n        <div class=\"phase-item\">Cloud Orchestrator WebSocket client</div>\n        <div class=\"phase-item\">Agent Runner + DOM event dispatch</div>\n        <div class=\"phase-item\">Approval flow UI in Side Panel</div>\n        <div class=\"phase-item\">Full E2E pipeline tested on real sites</div>\n      </div>\n      <div class=\"phase-card p4\">\n        <div class=\"phase-label\">Week 10&#x2013;12</div>\n        <div class=\"phase-title\">Polish &amp; Ship</div>\n        <div class=\"phase-item\">Performance optimization + profiling</div>\n        <div class=\"phase-item\">Security audit + pen test</div>\n        <div class=\"phase-item\">Web Store submission prep</div>\n        <div class=\"phase-item\">Demo recording for SIH submission</div>\n      </div>\n    </div>"
};
